or:#fff;border-color:transparent}.security-panel summary{cursor:pointer;padding:16px 0;font-size:12px;font-weight:600}.security-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:22px}.security-choice{display:flex!important;gap:12px;align-items:flex-start;padding:16px;margin:0;border:1px solid var(--admin-border,#64748b44);border-radius:11px;cursor:pointer;min-width:0}.security-choice:has(input:checked){border-color:var(--admin-primary,#2563eb);background:color-mix(in srgb,var(--admin-primary,#2563eb) 6%,transparent)}.security-choice input{margin:2px 0 0;accent-color:var(--admin-primary,#2563eb);flex-shrink:0}.security-choice strong{font-size:12px;color:var(--admin-text-heading);line-height:1.5}.security-choice small{display:block;color:var(--admin-text-muted);font-size:11px;line-height:1.7;margin-top:6px}.recovery-codes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;user-select:all;padding:16px;background:#64748b18;border-radius:10px}.security-secret{display:block;overflow-wrap:anywhere;user-select:all;padding:14px;border:1px dashed #64748b;border-radius:9px;letter-spacing:2px}.security-history{overflow:auto}.security-history table{width:100%;border-collapse:collapse;font-size:11px}.security-history td,.security-history th{padding:12px 8px;text-align:left;border-bottom:1px solid var(--admin-border,#64748b22);overflow-wrap:anywhere}.security-history th{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--admin-text-muted)}.security-history tbody tr:last-child td{border-bottom:0}.security-admin{margin-top:24px}.security-admin code{overflow-wrap:anywhere}.account-security>.security-panel{margin-bottom:24px}.security-panel .btn:focus-visible,.security-panel summary:focus-visible{outline:2px solid var(--admin-primary,#2563eb);outline-offset:3px}
