<?php else: ?>
<form method="post"><input type="hidden" name="_token" value="<?= $token ?>">
<?php if($state->method==='off'): ?><input type="hidden" name="action" value="setup"><label for="two-step-method">Verification method</label><select name="method" id="two-step-method"><option value="app">Authenticator app</option><option value="email">Email code</option></select><p>Setup activates only after you verify a code. Recovery codes are included with either method.</p><?php endif ?>
