</form><?php endif ?></section><section class="security-panel"><h2>Recent email delivery</h2><p>Delivery status means the message was handed to the configured email provider. Check your spam folder if it is missing.</p><div class="security-history"><table><thead><tr><th>Message</th><th>Status</th><th>Time (UTC)</th></tr></thead><tbody><?php foreach($history as $notice): ?><tr><td><?= $e($notice->subject) ?></td><td><?= $e($notice->status) ?><?php if($notice->last_error): ?><small> — <?= $e($notice->last_error) ?></small><?php endif ?></td><td><?= $e($notice->sent_at??$notice->created_at) ?></td></tr><?php endforeach ?><?php if(!$history): ?><tr><td colspan="3">No emails queued yet.</td></tr><?php endif ?></tbody></table></div></section></div>
