<label class="security-choice"><input type="checkbox" name="notice_<?= $key ?>" value="1" <?= !empty($prefs[$key])?'checked':'' ?>><span><strong><?= $e($label[0]) ?></strong><small><?= $e($label[1]) ?></small></span></label><?php endforeach ?></div><button class="btn btn-primary">Save email preferences</button></form></section></div>

